function maxScore(nums) {
  const n = nums.length;
  let total = 0;
  for (const value of nums) {
    total += value;
  }
  if (n % 2 === 1) {
    // Odd length: one number survives, and it can be any of them.
    let smallest = nums[0];
    for (const value of nums) {
      smallest = Math.min(smallest, value);
    }
    return total - smallest;
  }
  // Even length: two neighbours survive, and they can be any adjacent pair.
  let smallestPair = nums[0] + nums[1];
  for (let i = 1; i + 1 < n; i++) {
    smallestPair = Math.min(smallestPair, nums[i] + nums[i + 1]);
  }
  return total - smallestPair;
}

