function generate(rand, size) {
  const ranges = [[-3, 3], [-10, 10], [1, 10000], [-10000, -1], [-10000, 10000]];
  const [low, high] = ranges[Math.floor(rand() * ranges.length)];
  // Large inputs alternate between odd and even lengths, since the two cases are solved differently.
  const n = size === 'large' ? 1999 + Math.floor(rand() * 2) : 1 + Math.floor(rand() * 10);
  return [Array.from({ length: n }, () => low + Math.floor(rand() * (high - low + 1)))];
}
